BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL transaction_timeout='10s'; SET LOCAL statement_timeout='5s'; SET LOCAL lock_timeout='2s'; SET LOCAL search_path=pg_catalog;
SELECT json_build_object('database',current_database(),'physical_bytes',pg_database_size(current_database()),'other_sessions',(SELECT count(*) FROM pg_stat_activity WHERE datname=current_database() AND pid<>pg_backend_pid()),'kv_keys',(SELECT json_agg(key ORDER BY key) FROM public.pi_kv),'auth_users',(SELECT count(*) FROM public.pi_kv k CROSS JOIN LATERAL jsonb_object_keys(k.document->'users') u WHERE k.key='auth'),'auth_projects',(SELECT count(*) FROM public.pi_kv k CROSS JOIN LATERAL jsonb_object_keys(k.document->'projects') p WHERE k.key='auth'),'sole_owners',(SELECT bool_and((SELECT count(*) FROM jsonb_object_keys(p.value->'members'))=1 AND NOT EXISTS(SELECT 1 FROM jsonb_each_text(p.value->'members') m WHERE m.value<>'owner')) FROM public.pi_kv k CROSS JOIN LATERAL jsonb_each(k.document->'projects') p WHERE k.key='auth'),'auth_stable_sha256',(SELECT encode(sha256(jsonb_send(document-'sessions')),'hex') FROM public.pi_kv WHERE key='auth'),'projects',(SELECT jsonb_agg(jsonb_build_object('id',project_id,'conversions',document->'conversions') ORDER BY project_id) FROM public.pi_projects));
COMMIT;
SELECT 'DR24_COHORT_COMMITTED_V1';
